static const unsigned long bender_aot_names_len = sizeof(bender_aot_names) / sizeof(bender_aot_names[0]);

  int main(int argc, char **argv) {
      /* Remove the launcher switch before passing argv into Bender. */
      const char *work_path = NULL;
      for (int ai = 1; ai < argc; ai++) {
          if (!strcmp(argv[ai], "--work-profile")) {
              if (work_path || ai + 1 >= argc || !argv[ai + 1][0]) {
                  fprintf(stderr, "--work-profile requires one file path or '-'\n");
                  return 2;
              }
              work_path = argv[++ai];
              memmove(argv + ai - 1, argv + ai + 1,
                      (size_t)(argc - ai) * sizeof(*argv));
              argc -= 2;
              ai -= 2;
          }
      }
      if (work_path) {
#if !defined(BENDER_AOT_NATIVE_INIT) || (defined(BENDER_NATIVE_TELEMETRY) && !BENDER_NATIVE_TELEMETRY)
          fprintf(stderr, "--work-profile requires a telemetry-enabled native build\n");
          return 2;
#else
          if (!getenv("BENDER_NO_PROFILE")) {
              fprintf(stderr, "--work-profile requires BENDER_NO_PROFILE=1\n");
              return 2;
          }
          extern void native_work_profile_path(const char *path);
          native_work_profile_path(work_path);
#endif
      }
      bender_init();
#ifndef BENDER_NO_PGO
      /* The VM owns its auto-PGO output across both normal and os/exit
       * teardown. No launcher-owned process environment is needed. */
      /* Auto-PGO collects the first qualifying run to the base cache.
       * BENDER_AUTO_PGO=1 records further runs in unique sidecars,
       * merged fail-closed at the next native build. Never overwrite
       * existing evidence. BENDER_NO_PROFILE disables collection;
       * failures here silently run clean.
       * Locked-down targets (iOS: no JIT/dynamic codegen) compile
       * the whole mechanism out with -DBENDER_NO_PGO. */
      {
          const char *noprof = getenv("BENDER_NO_PROFILE");
          const char *force = getenv("BENDER_AUTO_PGO");
          const char *xdg = getenv("XDG_CACHE_HOME");
          const char *home = getenv("HOME");
          char base[64];
          char dir[4096];
          char path[4096];
          dir[0] = '\0';
          if (!noprof) {
              if (xdg && xdg[0] != '\0')
                  snprintf(dir, sizeof(dir), "%s/bender/pgo", xdg);
              else if (home && home[0] != '\0')
                  snprintf(dir, sizeof(dir), "%s/.cache/bender/pgo", home);
          }
          path[0] = '\0';
          if (dir[0] != '\0') {
              bender_aot_key(base, sizeof(base), (argc > 0) ? argv[0] : NULL);
              snprintf(path, sizeof(path), "%s/%s.jdn", dir, base);
          }
          if (path[0] != '\0' && (force || !BENDER_AOT_PROBE(path))) {
              bender_aot_mkdirp(dir);
              { /* Reserve a private destination for every collector. */
                   char sidecar[4096];
                   unsigned attempt;
                   for (attempt = 0; attempt < 64; attempt++) {
                       int fd;
                       snprintf(sidecar, sizeof(sidecar), "%s.%s-%ld-%u.pending",
                                path, BENDER_AOT_PROBE(path) ? "run" : "first",
                                 (long) getpid(), attempt);
                       fd = open(sidecar, O_WRONLY | O_CREAT | O_EXCL, 0600);
                       if (fd < 0) continue;
                       close(fd);
                       snprintf(path, sizeof(path), "%s", sidecar);
                       break;
                   }
                   if (attempt == 64) path[0] = 0;
               }
               if (path[0] != 0) {
                   bender_profile_start();
                   bender_profile_auto_output(path);
                   /* Record what this run is, so a later --pgo-auto build
                    * can replay it through the same parity gate as --pgo. */
                   bender_profile_auto_workload(argc, argv, bender_aot_image_len);
               }
          }
      }
#endif
      BenderTable *env = bender_core_env(NULL);
      bender_table_put(env, bender_ckeywordv("executable"), bender_cstringv(argv[0]));
#ifdef BENDER_AOT_NATIVE_INIT
      /* hybrid binary: register native kernels before any bender code
       * runs (boxed or eval'd call sites resolve through env) */
      extern void native_init(BenderTable *env);
      native_init(env);
#endif
      /* CLI parity: install (dyn :args) as [program, ...argv], the way
       * run.c exposes script arguments (mkimage note: :args[0] is the
       * script path). */
      BenderArray *cliargs = bender_array(argc > 0 ? argc : 1);
      for (int ai = 0; ai < argc; ai++)
          bender_array_push(cliargs, bender_cstringv(argv[ai]));
      bender_table_put(env, bender_ckeywordv("args"), bender_wrap_array(cliargs));
      /* CLI parity: -e CODE, the way the interpreter binary handles it.
      ** The interpreter's os/spawn falls back to argv[0] for bare
      ** program names, so subprocess tests like suite-ev's
      ** [bender -e "(print ...)"] exec THIS binary — which must eval
      ** the code, not re-run the embedded image. */
      for (int ai = 1; ai < argc; ai++) {
          if (argv[ai][0] == '-' && argv[ai][1] == 'e' &&
                  argv[ai][2] == '\0') {
              const char *code = (ai + 1 < argc) ? argv[ai + 1] : "";
              Bender out;
              int esig = bender_dostring(env, code, "-e", &out);
              if (esig != BENDER_SIGNAL_OK && esig != BENDER_SIGNAL_EVENT) {
                  bender_eprintf("%v\n", out);
                  bender_deinit();
                  return 1;
              }
              bender_deinit();
              return 0;
          }
      }
      BenderTable *reg = bender_table((int32_t) bender_aot_names_len);
      for (unsigned long i = 0; i < bender_aot_names_len; i++) {
          Bender v = bender_resolve_core(bender_aot_names[i]);
          if (!bender_checktype(v, BENDER_NIL))
              bender_table_put(reg, bender_csymbolv(bender_aot_names[i]), v);
      }
      bender_gcroot(bender_wrap_table(reg));
      /* Chunk env: one fresh table proto-linked to the module env.
      ** run-context gives script fibers an env whose proto is the
      ** module env; a bare core env has no proto, so scripts doing
      ** (table/getproto (curenv)) saw nil and broke (the shared-store
      ** escape test). Shared by all chunks so cross-form setdyn sees
      ** earlier forms, exactly like the interpreter's script runs. */
      BenderTable *chunk_env = bender_table(0);
      chunk_env->proto = env;
      bender_gcroot(bender_wrap_table(chunk_env));
      Bender top = bender_unmarshal(bender_aot_image, bender_aot_image_len, 0, reg, NULL);
      if (bender_checktype(top, BENDER_NIL)) {
          fprintf(stderr, "aot: unmarshal failed\n");
          bender_deinit();
          return 2;
      }
      bender_gcroot(top);
      /* Per-form chunks: the image is a tuple of functions (one per
      ** top-level form), run in order — the way run.c executes a
      ** script form by form. A bare function means a legacy
      ** one-chunk image. Mirror run.c bender_dobytes per chunk: run
      ** to completion, then enter the event loop for ev programs
      ** (bender_loop_fiber as in shell.c: quantum-INTERRUPT resumes
      ** need the scheduler to requeue them, and ev programs pump in
      ** the same loop). An error aborts the script with status 1. */
      int status = 0;
      int chunks_ok = 1;
      if (bender_checktype(top, BENDER_TUPLE)) {
          /* Chunks run from a rooted ARRAY with each slot cleared as
           * its chunk is taken (and again after it completes): a
           * finished chunk's function — and the constants its def
           * references — must become collectable, the way an
           * interpreter script's form functions die after their form.
           * Rooting all chunk functions for the whole run pinned def
           * constants forever; weak-table tests saw entries that
           * should have cleared post-gccollect. */
          BenderTuple chunks = bender_unwrap_tuple(top);
          BenderArray *chunk_arr = bender_array(bender_tuple_length(chunks));
          for (int32_t ci = 0; ci < bender_tuple_length(chunks); ci++)
              bender_array_push(chunk_arr, chunks[ci]);
          bender_gcunroot(top);
          bender_gcroot(bender_wrap_array(chunk_arr));
          /* ONE fiber for all chunks, re-primed per chunk — run-context
           * reuses a single evaluation context for a script's forms;
           * fresh-fiber-per-chunk left every completed chunk's STACK
           * live in retained dead fibers, pinning frame values so weak
           * tables never cleared their entries (K3 in the bisection).
           * bender_fiber_reset re-primes in place; later chunks
           * overwrite earlier stacks. */
          BenderFunction *first_fn =
              bender_unwrap_function(chunk_arr->data[0]);
          BenderFiber *fiber = bender_fiber(first_fn, 64, 0, NULL);
          fiber->env = chunk_env;
          bender_gcroot(bender_wrap_fiber(fiber));
          for (int32_t ci = 0; ci < chunk_arr->count; ci++) {
              if (!bender_checktype(chunk_arr->data[ci], BENDER_FUNCTION)) {
                  chunk_arr->data[ci] = bender_wrap_nil();
                  continue;
              }
              BenderFunction *fn =
                  bender_unwrap_function(chunk_arr->data[ci]);
              chunk_arr->data[ci] = bender_wrap_nil();
              if (ci > 0) {
                  bender_fiber_reset(fiber, fn, 0, NULL);
                  fiber->env = chunk_env;
                  /* Zero the reused stack: an open funcenv marshal
                   * (ev/do-thread thunks) reads ALL length slots of
                   * the enclosing frame, including slots this chunk
                   * has not written yet — without the zero they hold
                   * stale values from PREVIOUS chunks (an os/process
                   * from an earlier test made the marshal refuse).
                   * Nil-filled slots are safe to walk. */
                  memset(fiber->data, 0,
                         sizeof(Bender) * (size_t) fiber->capacity);
              }
              int fstatus = bender_loop_fiber(fiber);
              if (fstatus != BENDER_SIGNAL_OK && fstatus != BENDER_SIGNAL_EVENT) {
                  bender_stacktrace_ext(fiber, fiber->last_value, "");
                  status = 1;
                  chunks_ok = 0;
                  break;
              }
          }
          bender_gcunroot(bender_wrap_fiber(fiber));
          bender_gcunroot(bender_wrap_array(chunk_arr));
      } else if (bender_checktype(top, BENDER_FUNCTION)) {
          BenderFunction *fn = bender_unwrap_function(top);
          BenderFiber *fiber = bender_fiber(fn, 64, 0, NULL);
          fiber->env = chunk_env;
          bender_gcroot(bender_wrap_fiber(fiber));
          int fstatus = bender_loop_fiber(fiber);
          if (fstatus != BENDER_SIGNAL_OK && fstatus != BENDER_SIGNAL_EVENT) {
              bender_stacktrace_ext(fiber, fiber->last_value, "");
              status = 1;
          }
          bender_gcunroot(bender_wrap_fiber(fiber));
      }
      /* run-main parity: the interpreter's run-context calls
      ** (main ;subargs) after the script chunk completes (boot.ben
      ** run-main). AOT binaries skipped that step entirely — scripts
      ** that only define main ran as silent empty binaries. Mirror
      ** it: look up main in the script env and run it with argv[1..]
      ** (everything after the program name), same fiber-driving and
      ** ev-loop rules as the chunk. */
      if (chunks_ok) {
          /* mkimage appends (setdyn :aot-main main) when the script
          ** defines a top-level main — main is a mere local of its
          ** chunk, unreachable from C by name. setdyn lands in the
          ** chunk env (the current fiber env), so read it there and
          ** run it, exactly what run-main would have used. */
          Bender mainv = bender_table_get(chunk_env, bender_ckeywordv("aot-main"));
          BenderTable *script_env = chunk_env;
          if (bender_checktype(mainv, BENDER_FUNCTION)) {
              BenderArray *ma = bender_array(argc > 1 ? argc - 1 : 0);
              for (int ai = 1; ai < argc; ai++)
                  bender_array_push(ma, bender_cstringv(argv[ai]));
              BenderFiber *mfb = bender_fiber(bender_unwrap_function(mainv),
                                            64, ma->count, ma->data);
              mfb->env = script_env;
              bender_gcroot(bender_wrap_fiber(mfb));
              int mstatus = bender_loop_fiber(mfb);
              if (mstatus != BENDER_SIGNAL_OK && mstatus != BENDER_SIGNAL_EVENT) {
                  bender_stacktrace_ext(mfb, mfb->last_value, "");
                  status = 1;
              }
              bender_gcunroot(bender_wrap_fiber(mfb));
          }
      }
      bender_gcunroot(bender_wrap_table(chunk_env));
      if (bender_checktype(top, BENDER_TUPLE)) {
          /* already unrooted when the chunks moved into the array */
      } else {
          bender_gcunroot(top);
      }
      bender_deinit();
      return status;
  }
  